<?php
declare(strict_types=1);
namespace Brebo\Office\Project\Workspace;
final class TaskViews {
  public const STATUSES=['planned'=>'Gepland','active'=>'In uitvoering','blocked'=>'Geblokkeerd','done'=>'Gereed'];
  private static function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
  public static function signal(array $task,string $today):array {
    if($task['status']==='blocked')return ['red','Geblokkeerd',$task['reason']?:'Blokkade vastgelegd.'];
    if($task['status']==='done')return ['green','Gereed','Taak afgerond op '.($task['completed_on']??'onbekende datum').'.'];
    if($task['due_date']<$today)return ['red','Te laat','Einddatum '.$task['due_date'].' verstreken; taak is niet gereed.'];
    if((int)($task['assignee_person_id']??0)===0)return ['amber','Toewijzen','Nog geen verantwoordelijke gekozen.'];
    if($task['due_date']<=(new \DateTimeImmutable($today))->modify('+7 days')->format('Y-m-d'))return ['amber','Deze week','Open taak eindigt binnen zeven dagen.'];
    return ['gray','Gepland','Geen blokkade geregistreerd; nog niet afgerond.'];
  }
  public static function signals(array $r):string {
    $counts=['red'=>0,'amber'=>0,'green'=>0,'gray'=>0];$attention='';foreach($r['tasks'] as $t){[$tone,$label,$why]=self::signal($t,$r['today']);$counts[$tone]++;if(in_array($tone,['red','amber'],true))$attention.='<li><a href="/office-test/projecten/detail?id='.(int)$r['project_id'].'&amp;tab=taken&amp;task='.(int)$t['id'].'#taak-'.(int)$t['id'].'">'.self::e($t['title']).'</a> · <span class="pw-signal '.$tone.'">'.$label.'</span> '.self::e($why).'</li>';}
    $h='<section class="pw-panel"><h3>Stoplichten en eerstvolgende acties</h3><div class="pt-signals">';foreach(['red'=>'Kritiek / geblokkeerd','amber'=>'Aandacht','green'=>'Gereed','gray'=>'Gepland / onbekend'] as $tone=>$label)$h.='<span class="pw-signal '.$tone.'">'.$counts[$tone].' '.$label.'</span>';$h.='</div>'.($attention?'<ul>'.$attention.'</ul>':'<p>'.($r['tasks']?'Geen kritieke of aandacht vragende taken volgens de vastgelegde taakgegevens.':'Nog geen projecttaken vastgelegd; taakstatus is onbekend.').'</p>');
    foreach(['Kwaliteit','Risico’s','Inkoop'] as $domain)$h.='<span class="pw-signal gray">'.$domain.': bron nog niet aangesloten</span> ';
    return $h.'<p><small>Rood: blokkade of open taak na einddatum. Oranje: ontbrekende verantwoordelijke of einddatum binnen zeven dagen. Groen: afgerond. Grijs: gepland of onbekend. Dit is geen vrijgave voor kwaliteit, veiligheid of betaling.</small></p></section>';
  }
  private static function link(array $r,array $query):string{return '/office-test/projecten/detail?'.http_build_query(['id'=>$r['project_id'],'tab'=>'taken',...$query],'','&',PHP_QUERY_RFC3986);}
  public static function render(array $r,string $csrf,array $query=[],array $post=[]):string {
    $scalar=static fn(string $k,string $default=''):string=>is_string($query[$k]??null)?$query[$k]:$default;
    $view=$scalar('view','lijst');if(!in_array($view,['lijst','kanban','gantt','kalender'],true))$view='lijst';$status=$scalar('status');$owner=$scalar('owner');$search=substr($scalar('q'),0,200);$sort=$scalar('sort','due');if(!in_array($sort,['due','title','start'],true))$sort='due';$month=$scalar('month',substr($r['today'],0,7));if(!preg_match('/^20\d\d-(?:0[1-9]|1[0-2])$/D',$month))$month=substr($r['today'],0,7);
    $state=['view'=>$view,'status'=>$status,'owner'=>$owner,'q'=>$search,'sort'=>$sort,'month'=>$month];$team=[];foreach($r['team']??[] as $p)$team[(int)$p['id']]=$p;
    $tasks=array_values(array_filter($r['tasks'],static function($t)use($status,$owner,$search){return (!$status||$t['status']===$status)&&($owner===''||(int)($t['assignee_person_id']??0)===(int)$owner)&&($search===''||stripos($t['title'].' '.$t['description'],$search)!==false);}));
    $field=['due'=>'due_date','title'=>'title','start'=>'starts_on'][$sort];usort($tasks,static fn($a,$b)=>[$a[$field],(int)$a['id']]<=>[$b[$field],(int)$b['id']]);
    $h=self::styles().'<div class="pw pt"><header class="pw-head"><h2>Taken en planning</h2><p>Eén takenbestand · vier weergaven · '.count($tasks).' van '.count($r['tasks']).' taken</p></header><nav class="pt-views" aria-label="Taakweergave">';foreach(['gantt'=>'Gantt','kanban'=>'Kanban','kalender'=>'Kalender','lijst'=>'Lijst'] as $key=>$label)$h.='<a href="'.self::e(self::link($r,[...$state,'view'=>$key])).'"'.($view===$key?' aria-current="page"':'').'>'.$label.'</a>';$h.='</nav><form method="get" class="pt-filters"><input type="hidden" name="id" value="'.(int)$r['project_id'].'"><input type="hidden" name="tab" value="taken"><input type="hidden" name="view" value="'.$view.'"><input type="hidden" name="month" value="'.$month.'"><label>Zoeken<input name="q" value="'.self::e($search).'" maxlength="200"></label><label>Status<select name="status"><option value="">Alle statussen</option>';foreach(self::STATUSES as $k=>$v)$h.='<option value="'.$k.'"'.($status===$k?' selected':'').'>'.$v.'</option>';$h.='</select></label><label>Verantwoordelijke<select name="owner"><option value="">Iedereen</option><option value="0"'.($owner==='0'?' selected':'').'>Niet toegewezen</option>';foreach($team as $id=>$p)$h.='<option value="'.$id.'"'.($owner===(string)$id?' selected':'').'>'.self::e($p['display_name']).'</option>';$h.='</select></label><label>Sortering<select name="sort">';foreach(['due'=>'Einddatum','start'=>'Startdatum','title'=>'Naam'] as $k=>$v)$h.='<option value="'.$k.'"'.($sort===$k?' selected':'').'>'.$v.'</option>';$h.='</select></label><button>Toepassen</button></form>';
    $counts=array_fill_keys(array_keys(self::STATUSES),0);foreach($tasks as $t)$counts[$t['status']]++;$h.='<section class="pw-panel"><h3>Taakverdeling</h3><div class="pt-distribution" role="img" aria-label="'.self::e(implode(', ',array_map(static fn($k)=>self::STATUSES[$k].': '.$counts[$k],array_keys($counts)))).'">';foreach($counts as $k=>$n)if($n)$h.='<span class="pt-'.$k.'" style="flex:'.$n.'">'.$n.' '.self::STATUSES[$k].'</span>';$h.='</div></section>';
    if(!$tasks)$h.='<section class="pw-panel"><h3>Geen taken in deze selectie</h3><p>Pas de filters aan of voeg een projecttaak toe.</p></section>';
    elseif($view==='kanban'){$h.='<div class="pt-kanban">';foreach(self::STATUSES as $s=>$label){$h.='<section aria-label="'.$label.'"><h3>'.$label.' <small>'.$counts[$s].'</small></h3>';foreach($tasks as $t)if($t['status']===$s)$h.=self::card($t,$r,$team);$h.='</section>';}$h.='</div>';}
    elseif($view==='kalender'){$first=new \DateTimeImmutable($month.'-01');$start=$first->modify('monday this week');$last=$first->modify('last day of this month')->modify('sunday this week');$h.='<section class="pw-panel"><div class="pt-month"><a href="'.self::e(self::link($r,[...$state,'month'=>$first->modify('-1 month')->format('Y-m')])).'">← Vorige</a><h3>'.$first->format('m-Y').'</h3><a href="'.self::e(self::link($r,[...$state,'month'=>$first->modify('+1 month')->format('Y-m')])).'">Volgende →</a></div><div class="pw-scroll"><div class="pt-calendar">';foreach(['Ma','Di','Wo','Do','Vr','Za','Zo'] as $day)$h.='<strong>'.$day.'</strong>';for($day=$start;$day<=$last;$day=$day->modify('+1 day')){$d=$day->format('Y-m-d');$h.='<div class="pt-day'.($d===$r['today']?' pt-today':'').'"><time datetime="'.$d.'">'.$day->format('d-m').'</time>';foreach($tasks as $t)if($t['starts_on']<=$d&&$t['due_date']>=$d)$h.='<a class="pt-calendar-task pt-'.$t['status'].'" href="#taak-'.(int)$t['id'].'">#'.(int)$t['id'].' '.self::e($t['title']).'</a>';$h.='</div>';}$h.='</div></div></section>';}
    elseif($view==='gantt'){$from=min([...array_column($tasks,'starts_on'),...array_column($tasks,'baseline_start')]);$until=max([...array_column($tasks,'due_date'),...array_column($tasks,'baseline_end')]);$a=new \DateTimeImmutable($from);$days=max(1,(int)$a->diff(new \DateTimeImmutable($until))->days+1);$h.='<section class="pw-panel"><h3>Gantt · '.self::e($from).' – '.self::e($until).'</h3><p>Omlijnd: oorspronkelijke planning. Gekleurd: huidige planning; donkere vulling: vastgelegde taakvoortgang. Voorgangers staan per taak vermeld.</p><div class="pw-scroll"><div class="pt-gantt">';foreach($tasks as $t){$offset=static fn($d)=>100*(int)$a->diff(new \DateTimeImmutable($d))->days/$days;$left=$offset($t['starts_on']);$width=100*((int)(new \DateTimeImmutable($t['starts_on']))->diff(new \DateTimeImmutable($t['due_date']))->days+1)/$days;$bl=$offset($t['baseline_start']);$bw=100*((int)(new \DateTimeImmutable($t['baseline_start']))->diff(new \DateTimeImmutable($t['baseline_end']))->days+1)/$days;$h.='<div class="pt-gantt-label"><a href="#taak-'.(int)$t['id'].'">#'.(int)$t['id'].' '.self::e($t['title']).'</a><small>'.self::e($t['starts_on'].' → '.$t['due_date']).' · '.(int)$t['progress_percent'].'%'.($t['predecessors']?' · na #'.implode(', #',$t['predecessors']):'').'</small></div><div class="pt-gantt-track"><span class="pt-baseline" style="left:'.$bl.'%;width:'.$bw.'%" title="Oorspronkelijk: '.$t['baseline_start'].' – '.$t['baseline_end'].'"></span><span class="pt-current pt-'.$t['status'].'" style="left:'.$left.'%;width:'.$width.'%"><span style="width:'.(int)$t['progress_percent'].'%"></span></span></div>';}$h.='</div></div></section>';}
    else{$h.='<section class="pw-panel pw-scroll"><table><thead><tr><th>Taak</th><th>Verantwoordelijke</th><th>Periode</th><th>Status</th><th>Voortgang</th><th>Voorgangers</th><th>Stoplicht</th></tr></thead><tbody>';foreach($tasks as $t){[$tone,$label,$why]=self::signal($t,$r['today']);$h.='<tr><td><a href="#taak-'.(int)$t['id'].'">#'.(int)$t['id'].' '.self::e($t['title']).'</a></td><td>'.self::e($team[(int)$t['assignee_person_id']]['display_name']??'Niet toegewezen').'</td><td>'.self::e($t['starts_on'].' / '.$t['due_date']).'</td><td>'.self::STATUSES[$t['status']].'</td><td>'.(int)$t['progress_percent'].'%</td><td>'.self::e(implode(', #',$t['predecessors'])).'</td><td><span class="pw-signal '.$tone.'" title="'.self::e($why).'">'.$label.'</span></td></tr>';}$h.='</tbody></table></section>';}
    if($r['can_manage'])$h.='<details'.(($post['action']??'')==='task'&&(int)($post['id']??0)===0?' open':'').'><summary>+ Taak toevoegen</summary>'.self::form($r,$csrf,[],$post).'</details>';
    $selected=(int)($query['task']??0);foreach($tasks as $t)$h.='<details id="taak-'.(int)$t['id'].'"'.($selected===(int)$t['id']||(($post['action']??'')==='task'&&(int)($post['id']??0)===(int)$t['id'])?' open':'').'><summary>#'.(int)$t['id'].' '.self::e($t['title']).' · '.self::STATUSES[$t['status']].'</summary>'.($r['can_manage']?self::form($r,$csrf,$t,$post):self::card($t,$r,$team)).'</details>';
    return $h.'</div>';
  }
  private static function card(array $t,array $r,array $team):string{[$tone,$label,$why]=self::signal($t,$r['today']);return '<article class="pt-card"><a href="#taak-'.(int)$t['id'].'"><strong>#'.(int)$t['id'].' '.self::e($t['title']).'</strong></a><p>'.self::e($team[(int)$t['assignee_person_id']]['display_name']??'Niet toegewezen').'</p><p>'.self::e($t['starts_on'].' → '.$t['due_date']).'</p><progress max="100" value="'.(int)$t['progress_percent'].'">'.(int)$t['progress_percent'].'%</progress> '.(int)$t['progress_percent'].'%<p><span class="pw-signal '.$tone.'">'.$label.'</span> '.self::e($why).'</p><p class="pw-text">'.self::e($t['description']).'</p></article>';}
  public static function form(array $r,string $csrf,array $task,array $post=[]):string {
    $p=($post['action']??'')==='task'&&(int)($post['id']??0)===(int)($task['id']??0)?$post:$task;
    $h='<form class="pw-form" method="post" action="/office-test/projecten/beheer">';foreach(['project_id'=>$r['project_id'],'csrf'=>$csrf,'action'=>'task','id'=>$task['id']??0,'revision'=>$task['revision']??0,'command_key'=>bin2hex(random_bytes(16))] as $k=>$v)$h.='<input type="hidden" name="'.$k.'" value="'.self::e($v).'">';
    foreach(['title'=>'Taak','description'=>'Omschrijving','starts_on'=>'Startdatum','due_date'=>'Einddatum','estimated_minutes'=>'Begrote arbeid (minuten)','progress_percent'=>'Vastgelegde voortgang (%)','reason'=>'Blokkade / reden overdracht of delegatie'] as $k=>$label){$type=in_array($k,['starts_on','due_date'],true)?'date':(in_array($k,['estimated_minutes','progress_percent'],true)?'number':'text');$h.='<label>'.$label.'<input name="'.$k.'" type="'.$type.'" value="'.self::e($p[$k]??(in_array($type,['number'],true)?0:($type==='date'?$r['today']:''))).'"'.(in_array($k,['title','starts_on','due_date'],true)?' required':'').($type==='number'?' min="0"'.($k==='progress_percent'?' max="100"':''):'').'></label>';}
    $h.='<label>Status<select name="status">';foreach(self::STATUSES as $k=>$label)$h.='<option value="'.$k.'"'.(($p['status']??'planned')===$k?' selected':'').'>'.$label.'</option>';$h.='</select></label><label>Toewijzen / delegeren<select name="assignee_person_id"><option value="0">Nog niet toewijzen</option>';foreach($r['team']??[] as $person)if((int)$person['active']===1)$h.='<option value="'.(int)$person['id'].'"'.((int)($p['assignee_person_id']??0)===(int)$person['id']?' selected':'').'>'.self::e($person['display_name']).'</option>';$h.='</select></label><fieldset><legend>Voorgangers (eerst afronden)</legend>';foreach($r['tasks'] as $t)if((int)$t['id']!==(int)($task['id']??0))$h.='<label class="pw-check"><input type="checkbox" name="predecessors[]" value="'.(int)$t['id'].'"'.(in_array((int)$t['id'],array_map('intval',is_array($p['predecessors']??null)?$p['predecessors']:[]),true)?' checked':'').'>#'.(int)$t['id'].' '.self::e($t['title']).'</label>';$h.='</fieldset><p>De oorspronkelijke datums blijven als baseline bewaard. Een overdracht krijgt een auditregistratie. De medewerker ziet de taak zodra diens bestaande projecttoegang dat toestaat.</p><label class="pw-check"><input type="checkbox" name="confirmed" value="yes" required> Gegevens gecontroleerd</label><button>'.($task?'Taak opslaan':'Taak toevoegen').'</button></form>';return $h;
  }
  public static function labor(array $r):string {
    $h=self::styles().'<div class="pw"><header class="pw-head"><h2>Arbeid en uren</h2><p>Personeelsuren afzonderlijk van bedragen. Stand '.$r['today'].'.</p></header><div class="pw-kpis">';$estimate=array_sum(array_column($r['tasks'],'estimated_minutes'))/60;
    foreach([['Begrote taakarbeid',$r['tasks']?$estimate:null],['Geplande inzet t/m peildatum',$r['planned_seconds']===null?null:$r['planned_seconds']/3600],['Goedgekeurde OnSite-uren',$r['approved_seconds']===null?null:$r['approved_seconds']/3600]] as [$label,$n])$h.='<article class="pw-kpi pw-blue"><span>'.$label.'</span><strong>'.($n===null?'Onbekend':number_format($n,2,',','.').' uur').'</strong></article>';
    $h.='</div><section class="pw-panel"><h3>Planning tegenover goedgekeurde uren</h3>';$max=max(1,$r['planned_seconds']??0,$r['approved_seconds']??0);foreach(['planned_seconds'=>'Geplande inzet','approved_seconds'=>'Goedgekeurd'] as $key=>$label){$n=$r[$key];$h.='<div class="pw-bar-row"><span>'.$label.'</span><strong>'.($n===null?'Bron niet beschikbaar':number_format($n/3600,2,',','.').' uur').'</strong><div class="pw-track"><span style="width:'.($n===null?0:100*$n/$max).'%;background:'.($key==='planned_seconds'?'#778da7':'#218a89').'"></span></div></div>';}$h.='<p>Begrote taakarbeid betreft de hele taakplanning. Inzet en OnSite tonen uren tot en met dezelfde peildatum; ongekeurde registraties tellen niet mee. Taakbegroting wordt niet bij de personeelsplanning opgeteld.</p><p><a href="/office-test/projecten?view=inzet&amp;tab=planning&amp;shift_project='.(int)$r['project_id'].'">Inzetplanning</a> · <a href="/office-test/inzet/projectkaart?id='.(int)$r['project_id'].'">OnSite en urencontrole</a></p></section><section class="pw-panel"><h3>Begrote arbeid per taak</h3><div class="pw-scroll"><table><thead><tr><th>Taak</th><th>Arbeid begroot</th><th>Status</th></tr></thead><tbody>';foreach($r['tasks'] as $t)$h.='<tr><td>'.self::e($t['title']).'</td><td>'.number_format((int)$t['estimated_minutes']/60,2,',','.').' uur</td><td>'.self::STATUSES[$t['status']].'</td></tr>';return $h.'</tbody></table></div><p>Werkelijke uren worden op project geregistreerd. Er wordt geen verdeling over taken verondersteld.</p></section></div>';
  }
  public static function styles():string{return '<style>.pw{font-family:Roboto,Arial,sans-serif}.pt-views,.pt-signals,.pt-month{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:18px 0}.pt-views a{padding:10px 16px;border:1px solid #dbe3ec;border-radius:7px;background:white}.pt-views a[aria-current]{background:#1769aa;color:white}.pt-filters{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:20px 0}.pt-filters label{display:grid;gap:6px}.pt-filters input,.pt-filters select,.pt-filters button{font:inherit;padding:10px;border:1px solid #cbd7e3;border-radius:5px}.pt-filters button{background:#1769aa;color:white}.pt-kanban{display:grid;grid-template-columns:repeat(4,minmax(220px,1fr));gap:15px;overflow:auto}.pt-kanban>section{background:#eaf0f6;border-radius:10px;padding:14px}.pt-card{padding:15px;background:white;border:1px solid #dbe3ec;border-radius:9px;margin:12px 0;overflow-wrap:anywhere}.pt-card progress{width:75%;accent-color:#23866b}.pw-signal{display:inline-block;padding:5px 9px;border-radius:20px;font-size:12px;font-weight:600;margin:3px}.pw-signal:before{content:"● ";}.pw-signal.red{color:#9e2638;background:#fde9ed}.pw-signal.amber{color:#805615;background:#fff0cf}.pw-signal.green{color:#146a50;background:#dff4e9}.pw-signal.gray{color:#526478;background:#edf1f5}.pt-distribution{display:flex;gap:3px;min-height:35px;flex-wrap:wrap}.pt-distribution span{padding:9px;min-width:95px;border-radius:5px}.pt-planned{background:#d5e2f2;color:#263f5c}.pt-active{background:#cce9f8;color:#14516c}.pt-blocked{background:#f8d4dc;color:#9e2638}.pt-done{background:#c9eddf;color:#146a50}.pt-calendar{display:grid;grid-template-columns:repeat(7,minmax(120px,1fr));min-width:840px;gap:5px}.pt-day{min-height:120px;border:1px solid #dbe3ec;padding:7px;background:white}.pt-day time{font-weight:bold;display:block;margin-bottom:9px}.pt-today{outline:2px solid #1769aa;outline-offset:-2px}.pt-calendar-task{display:block;padding:5px;margin:4px 0;font-size:12px;border-radius:4px;overflow-wrap:anywhere}.pt-month{justify-content:space-between}.pt-gantt{display:grid;grid-template-columns:270px minmax(500px,1fr);min-width:790px;gap:8px}.pt-gantt-label{padding:9px;border-bottom:1px solid #e2e9f0}.pt-gantt-label small{display:block;margin-top:8px}.pt-gantt-track{position:relative;background:repeating-linear-gradient(90deg,#f5f7fa 0,#f5f7fa 9.8%,#dce4ed 10%);min-height:65px;border-bottom:1px solid #e2e9f0}.pt-baseline{position:absolute;height:14px;top:12px;box-sizing:border-box;border:2px solid #768ba2;border-radius:3px}.pt-current{position:absolute;height:16px;top:34px;border-radius:4px;overflow:hidden}.pt-current>span{display:block;height:100%;background:currentColor;opacity:.5}.pt fieldset{border:1px solid #cbd7e3;padding:15px;max-height:220px;overflow:auto}.pt .pw-form button{font-family:inherit}@media(max-width:760px){.pt-filters label{width:100%}.pt-kanban{grid-template-columns:repeat(4,250px)}}</style>';}
}
